package com.example.planyourtrip.config;
import com.example.planyourtrip.exception.ApiException; import com.example.planyourtrip.security.*; import org.springframework.core.MethodParameter; import org.springframework.http.HttpStatus; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.bind.support.WebDataBinderFactory; import org.springframework.web.context.request.NativeWebRequest; import org.springframework.web.method.support.*;
@Component public class AuthUserResolver implements HandlerMethodArgumentResolver { public boolean supportsParameter(MethodParameter p){ return p.hasParameterAnnotation(AuthUser.class) && p.getParameterType().equals(Long.class);} public Object resolveArgument(MethodParameter p, ModelAndViewContainer m, NativeWebRequest w, WebDataBinderFactory b){ Object principal= SecurityContextHolder.getContext().getAuthentication()==null?null:SecurityContextHolder.getContext().getAuthentication().getPrincipal(); if(principal instanceof UserPrincipal up) return up.id(); throw new ApiException(HttpStatus.UNAUTHORIZED,"Missing or invalid bearer token"); }}
